sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  var c = this;

  // Inicializa vazio
  c.selectedYear = "";

  function atualizarIndicador() {
    c.server.get({ selectedYear: c.selectedYear }).then(function(response) {
      c.data = response.data;
      // Debug para garantir que está vindo certo
      console.log("Widget Meta atualizado. Ano:", c.data.selectedYear, "Valor:", c.data.indicator.value);
    });
  }

  // Listener
  var destroyListener = $rootScope.$on('anoSelecionado', function(event, ano) {
    c.selectedYear = ano;
    atualizarIndicador();
  });

  // Boa prática: remove o listener se o widget for destruído (mudar de página)
  $scope.$on('$destroy', function() {
      destroyListener();
  });

  // Carga inicial
  atualizarIndicador();
}

sp_widget.css:
.financial-widget {
    border: 1px solid #ccc;
    border-radius: 4px;
    overflow: hidden;
  	margin-top: 4rem;
}

.indicator-block {
    text-align: center;
    padding: 0;
}

.indicator-header {
		background-color: #EBEDF1;
    color: #021770;
    font-weight: 400;
    padding: .8rem 1rem;
    font-size: 1.4rem;
    border-bottom: .1rem solid #C7C7C7
}

.indicator-value {
    color: #021770;
    font-size: 32px;
    font-weight: 400;
    padding: 10px 10px 15px;
}

.separator {
    margin: 0;
    border: 0;
    border-top: 1px solid #e0e0e0;
}

sp_widget.script:
(function() {
  input = input || {};
  var table = 'x_sded9_portal_t_0_limite_de_endividamento';
  var selectedYear = input.selectedYear || "";

  // 1. Lógica para definir o ano padrão (Último ano disponível)
  // Adicionamos o filtro aqui também para garantir que buscamos o último ano DO INDICADOR CORRETO
  if (!selectedYear) {
    var g = new GlideRecord(table);
    g.addQuery('indicador_de_endividamento_publico', 'mga'); // <--- FILTRO IMPORTANTE
    g.orderByDesc('u_ano');
    g.setLimit(1);
    g.query();
    if (g.next())
      selectedYear = g.getValue('u_ano');
  }

  data.selectedYear = selectedYear;

  data.indicator = {
    value: '0%', 
    label: 'Meta ' + (selectedYear ? selectedYear : '')
  };

  // 2. Busca do registro final
  var gr = new GlideRecord(table);
  gr.addQuery('indicador_de_endividamento_publico', 'mga'); // <--- FILTRO IMPORTANTE

  if (selectedYear) {
    gr.addQuery('u_ano', selectedYear);
  }

  gr.orderByDesc('sys_created_on');
  gr.setLimit(1);
  gr.query();

  if (gr.next()) {
    var anoReal = gr.getValue('u_ano');
    var valorMeta = gr.getValue('u_meta') || '0'; // Pega a META

    // Formatação simples para garantir casas decimais (opcional, mas recomendado)
    // Se o banco guarda como "12,5", ok. Se guarda "12.5", ok.
    data.indicator.value = valorMeta + '%'; 
    data.indicator.label = 'Meta ' + anoReal; // Removi o ":" para ficar mais limpo
    data.selectedYear = anoReal;
  }

})();
